# Autogenerated pairs trading strategy for vectorbt backtesting
# Includes compute_spread_indicators and order_func required by the runner.

from typing import Any, Dict, Tuple

import numpy as np
import pandas as pd


def compute_spread_indicators(
    close_a: np.ndarray,
    close_b: np.ndarray,
    hedge_lookback: int = 60,
    zscore_lookback: int = 20,
) -> Dict[str, np.ndarray]:
    """Compute rolling hedge ratio (OLS) and z-score of the spread.

    Args:
        close_a: Price series for asset A (1D numpy array).
        close_b: Price series for asset B (1D numpy array).
        hedge_lookback: Lookback window (in bars) for rolling OLS to compute hedge ratio.
        zscore_lookback: Lookback window for rolling mean and std of the spread.

    Returns:
        A dictionary with at least the following keys:
            - "hedge_ratio": 1D numpy array of hedge ratios (slope of regression of A on B).
            - "zscore": 1D numpy array of z-scores for the spread.

    Notes:
        - Uses simple OLS (np.polyfit) on each rolling window. Windows with insufficient
          non-NaN observations produce NaNs.
        - Spread is defined as: spread = Price_A - hedge_ratio * Price_B
        - Z-score is computed with rolling mean/std using pandas (aligned to right edge).
    """
    # Basic validation
    if close_a is None or close_b is None:
        raise ValueError("close_a and close_b must be provided as numpy arrays")

    close_a = np.asarray(close_a, dtype=float)
    close_b = np.asarray(close_b, dtype=float)

    if close_a.ndim != 1 or close_b.ndim != 1:
        raise ValueError("close_a and close_b must be 1D arrays")

    if len(close_a) != len(close_b):
        raise ValueError("close_a and close_b must have the same length")

    n = len(close_a)

    # Initialize hedge ratio array with NaNs
    hedge_ratio = np.full(n, np.nan, dtype=float)

    # Rolling OLS (slope only) for each window end at i
    # We require at least 2 non-NaN points to fit a line
    start_idx = 0
    for end_idx in range(n):
        start_idx = end_idx - hedge_lookback + 1
        if start_idx < 0:
            continue
        window_x = close_b[start_idx : end_idx + 1]
        window_y = close_a[start_idx : end_idx + 1]
        mask = ~np.isnan(window_x) & ~np.isnan(window_y)
        if mask.sum() < 2:
            # Not enough data to fit
            continue
        x = window_x[mask]
        y = window_y[mask]
        # If x has zero variance, slope is undefined -> skip
        if np.allclose(x, x[0]):
            # If x constant but y also constant, slope may be zero; otherwise skip
            if np.allclose(y, y[0]):
                slope = 0.0
            else:
                # Skip to avoid division by zero
                continue
        else:
            # Fit linear regression y = slope * x + intercept
            # np.polyfit returns highest power first: [slope, intercept]
            try:
                slope, _ = np.polyfit(x, y, 1)
            except Exception:
                # Fallback to covariance formula
                x_mean = x.mean()
                y_mean = y.mean()
                cov = np.mean((x - x_mean) * (y - y_mean))
                var = np.mean((x - x_mean) ** 2)
                if var == 0:
                    continue
                slope = cov / var

        hedge_ratio[end_idx] = float(slope)

    # Compute spread
    spread = np.full(n, np.nan, dtype=float)
    valid_hr = ~np.isnan(hedge_ratio)
    spread[valid_hr] = close_a[valid_hr] - hedge_ratio[valid_hr] * close_b[valid_hr]

    # Compute rolling mean and std for z-score using pandas for correctness
    spread_series = pd.Series(spread)
    roll_mean = spread_series.rolling(window=zscore_lookback, min_periods=zscore_lookback).mean().to_numpy()
    roll_std = spread_series.rolling(window=zscore_lookback, min_periods=zscore_lookback).std(ddof=0).to_numpy()

    # Z-score calculation: guard against zero std
    zscore = np.full(n, np.nan, dtype=float)
    valid_z = ~np.isnan(spread) & ~np.isnan(roll_mean) & (roll_std > 0)
    zscore[valid_z] = (spread[valid_z] - roll_mean[valid_z]) / roll_std[valid_z]

    return {"hedge_ratio": hedge_ratio, "zscore": zscore}


def order_func(
    c: Any,
    close_a: np.ndarray,
    close_b: np.ndarray,
    zscore: np.ndarray,
    hedge_ratio: np.ndarray,
    entry_threshold: float,
    exit_threshold: float,
    stop_threshold: float,
    notional_per_leg: float,
) -> Tuple[float, int, int]:
    """Order function for a pairs trading strategy (flexible multi-asset mode).

    This function is designed to be called for each asset (col) on each bar. It returns
    a tuple (size, size_type, direction) where:
      - size: numeric size (interpreted according to size_type)
      - size_type: integer code for size type (we use 0 to indicate BY_SIZE/units)
      - direction: integer (1 = BUY/LONG, 2 = SELL/SHORT). If size is NaN, no order is placed.

    Logic implemented:
      - Entry when z-score > entry_threshold: SHORT A, LONG B
      - Entry when z-score < -entry_threshold: LONG A, SHORT B
      - Exit when z-score crosses 0 (sign change relative to previous bar)
      - Stop-loss when |z-score| > stop_threshold
      - Position sizing: fixed notional per leg used to compute base units for asset A.
        Units for B are scaled by the hedge_ratio: units_B = hedge_ratio * units_A.

    Notes:
      - This function intentionally returns simple Python tuples and avoids numba.
      - We use size_type = 0 (BY_SIZE / units). Direction mapping chosen to avoid negative
        integers which are rejected by the backend: 1 = buy, 2 = sell.
    """
    i = int(c.i)
    col = int(getattr(c, "col", 0))

    # Current position for this asset (signed units). If not provided, assume 0.
    pos_now = float(getattr(c, "position_now", 0.0) or 0.0)

    # Basic validation of inputs at this bar
    if i < 0 or i >= len(zscore) or i >= len(hedge_ratio):
        return (np.nan, 0, 0)

    price_a = float(close_a[i]) if not np.isnan(close_a[i]) else np.nan
    price_b = float(close_b[i]) if not np.isnan(close_b[i]) else np.nan
    z = float(zscore[i]) if not np.isnan(zscore[i]) else np.nan
    hr = float(hedge_ratio[i]) if not np.isnan(hedge_ratio[i]) else np.nan

    # If indicators or prices are not available, do nothing
    if np.isnan(z) or np.isnan(hr) or np.isnan(price_a) or np.isnan(price_b):
        return (np.nan, 0, 0)

    # Compute base units for asset A (BY_SIZE). Units for B follow hedge ratio.
    # Guard against zero price
    if price_a == 0 or price_b == 0:
        return (np.nan, 0, 0)

    units_a = float(notional_per_leg) / price_a
    units_b = float(hr) * units_a

    # Determine previous zscore for crossing detection
    prev_z = float(zscore[i - 1]) if i > 0 and not np.isnan(zscore[i - 1]) else np.nan

    # Helper to close current position for this asset
    def _close_position(sz_now: float) -> Tuple[float, int, int]:
        if sz_now == 0 or np.isnan(sz_now):
            return (np.nan, 0, 0)
        size = abs(sz_now)
        # If currently long (positive), close by selling -> direction = 2
        if sz_now > 0:
            return (size, 0, 2)
        # If currently short (negative), close by buying -> direction = 1
        return (size, 0, 1)

    # 1) Stop-loss: if |z| > stop_threshold -> close if we have a position
    if abs(z) > stop_threshold and pos_now != 0:
        return _close_position(pos_now)

    # 2) Exit: z-score crosses zero (sign change relative to previous bar) -> close
    if pos_now != 0 and not np.isnan(prev_z):
        # Cross from positive to non-positive or negative to non-negative
        if (prev_z > 0 and z <= exit_threshold) or (prev_z < 0 and z >= exit_threshold):
            return _close_position(pos_now)

    # 3) Entry: only when we don't have a position in this asset
    if pos_now == 0:
        # Short A, Long B when z > entry_threshold
        if z > entry_threshold:
            if col == 0:
                # Asset A: SHORT units_a -> direction = 2
                return (units_a, 0, 2)
            else:
                # Asset B: LONG units_b -> direction = 1
                if units_b >= 0:
                    return (abs(units_b), 0, 1)
                else:
                    # Negative units_b -> interpret as short
                    return (abs(units_b), 0, 2)

        # Long A, Short B when z < -entry_threshold
        if z < -entry_threshold:
            if col == 0:
                # Asset A: LONG units_a -> direction = 1
                return (units_a, 0, 1)
            else:
                # Asset B: SHORT units_b -> direction = 2
                if units_b >= 0:
                    return (abs(units_b), 0, 2)
                else:
                    return (abs(units_b), 0, 1)

    # Otherwise, do nothing
    return (np.nan, 0, 0)
